fn needs_animations_update(
    &self,
    context: &mut StyleContext<Self>,
    old_style: Option<&ComputedValues>,
    new_style: &ComputedValues,
    pseudo_element: Option<PseudoElement>,
) -> bool {
    let new_ui_style = new_style.get_ui();
    let new_style_specifies_animations = new_ui_style.specifies_animations();

    let has_animations = self.has_css_animations(context.shared, pseudo_element);
    if !new_style_specifies_animations && !has_animations {
        return false;
    }

    let old_style = match old_style {
        Some(old) => old,
        // If we have no old style but have animations, we may be a
        // pseudo-element which was re-created without style changes.
        //
        // This can happen when we reframe the pseudo-element without
        // restyling it (due to content insertion on a flex container or
        // such, for example). See bug 1564366.
        //
        // FIXME(emilio): The really right fix for this is keeping the
        // pseudo-element itself around on reframes, but that's a bit
        // harder. If we do that we can probably remove quite a lot of the
        // EffectSet complexity though, since right now it's stored on the
        // parent element for pseudo-elements given we need to keep it
        // around...
        None => {
            return new_style_specifies_animations || new_style.is_pseudo_style();
        },
    };

    let old_ui_style = old_style.get_ui();

    let keyframes_could_have_changed = context
        .shared
        .traversal_flags
        .contains(TraversalFlags::ForCSSRuleChanges);

    // If the traversal is triggered due to changes in CSS rules changes, we
    // need to try to update all CSS animations on the element if the
    // element has or will have CSS animation style regardless of whether
    // the animation is running or not.
    //
    // TODO: We should check which @keyframes were added/changed/deleted and
    // update only animations corresponding to those @keyframes.
    if keyframes_could_have_changed {
        return true;
    }

    // If the animations changed, well...
    if !old_ui_style.animations_equals(new_ui_style) {
        return true;
    }

    let old_display = *old_style.get_display();
    let new_display = *new_style.get_display();

    // If we were display: none, we may need to trigger animations.
    if old_display == Display::None && new_display != Display::None {
        return new_style_specifies_animations;
    }

    // If we are becoming display: none, we may need to stop animations.
    if old_display != Display::None && new_display == Display::None {
        return has_animations;
    }

    // We might need to update animations if writing-mode or direction
    // changed, and any of the animations contained logical properties.
    //
    // We may want to be more granular, but it's probably not worth it.
    if new_style.writing_mode != old_style.writing_mode {
        return has_animations;
    }

    if Self::requires_animation_update_for_scroll_self(old_style, new_style) {
        return has_animations;
    }

    false
}

#[cfg(feature = "gecko")]
fn process_animations(
    &self,
    context: &mut StyleContext<Self>,
    old_styles: &mut ElementStyles,
    new_styles: &mut ResolvedElementStyles,
    important_rules_changed: bool,
) {
    use crate::context::UpdateAnimationsTasks;

    let old_values = &old_styles.primary;
    if context.shared.traversal_flags.for_animation_only() && old_values.is_some() {
        return;
    }

    // Bug 868975: These steps should examine and update the visited styles
    // in addition to the unvisited styles.

    let mut tasks = UpdateAnimationsTasks::empty();

    if old_values.as_deref().map_or_else(
        || {
            new_styles
                .primary_style()
                .get_ui()
                .specifies_timeline_scope()
        },
        |old| {
            !old.get_ui()
                .timeline_scope_equals(new_styles.primary_style().get_ui())
        },
    ) {
        tasks.insert(UpdateAnimationsTasks::TIMELINE_SCOPES);
    }

    if old_values.as_deref().map_or_else(
        || {
            new_styles
                .primary_style()
                .get_ui()
                .specifies_scroll_timelines()
        },
        |old| {
            !old.get_ui()
                .scroll_timelines_equals(new_styles.primary_style().get_ui())
        },
    ) {
        tasks.insert(UpdateAnimationsTasks::SCROLL_TIMELINES);
    }

    if old_values.as_deref().map_or_else(
        || {
            new_styles
                .primary_style()
                .get_ui()
                .specifies_view_timelines()
        },
        |old| {
            !old.get_ui()
                .view_timelines_equals(new_styles.primary_style().get_ui())
        },
    ) {
        tasks.insert(UpdateAnimationsTasks::VIEW_TIMELINES);
    }

    if self.needs_animations_update(
        context,
        old_values.as_deref(),
        new_styles.primary_style(),
        /* pseudo_element = */ None,
    ) {
        tasks.insert(UpdateAnimationsTasks::CSS_ANIMATIONS);
        tasks.insert(UpdateAnimationsTasks::EFFECT_PROPERTIES);
    }

    let before_change_style =
        self.process_transitions(context, old_values.as_ref(), new_styles);
    if before_change_style.is_some() {
        tasks.insert(UpdateAnimationsTasks::CSS_TRANSITIONS);
    }

    if self.has_animations(context.shared) {
        tasks.insert(UpdateAnimationsTasks::EFFECT_PROPERTIES);
        if important_rules_changed {
            tasks.insert(UpdateAnimationsTasks::CASCADE_RESULTS);
        }
        if new_styles
            .primary_style()
            .is_display_property_changed_from_none(old_values.as_deref())
        {
            tasks.insert(UpdateAnimationsTasks::DISPLAY_CHANGED_FROM_NONE);
        }
    }

    if !tasks.is_empty() {
        let task = crate::context::SequentialTask::update_animations(
            *self,
            before_change_style,
            tasks,
        );
        context.thread_local.tasks.push(task);
    }
}

static void UpdateOldAnimationPropertiesWithNew(
    CSSAnimation& aOld, TimingParams&& aNewTiming,
    nsTArray<Keyframe>&& aNewKeyframes, bool aNewIsStylePaused,
    CSSAnimationProperties aOverriddenProperties,
    ServoCSSAnimationBuilder& aBuilder, const NonOwningAnimationTarget& aTarget,
    dom::AnimationTimeline* aTimeline,
    const dom::ScopedTimelineName& aTimelineName,
    const StyleComputedTimingFunction& aNewTimingFunction,
    dom::CompositeOperation aNewComposite, dom::AnimationRange&& aTimelineRange,
    nsAnimationManager::TimelineNamesToAnimationMap&
        aTimelineNamesToAnimationMap) {
  const auto oldTimelineName = aOld.GetTimelineName();
  const bool timelineReferenceChanged =
      aOld.GetTimeline() != aTimeline ||
      oldTimelineName.mName != aTimelineName.mName;
  if (timelineReferenceChanged && oldTimelineName.mName) {
    RemoveCorrespondingAnimation(oldTimelineName.mName, &aOld,
                                 aTimelineNamesToAnimationMap);
  }
  bool animationChanged = false;

  // Update the old from the new so we can keep the original object
  // identity (and any expando properties attached to it).
  if (dom::AnimationEffect* oldEffect = aOld.GetEffect()) {
    // Copy across the changes that are not overridden
    TimingParams updatedTiming = oldEffect->SpecifiedTiming();
    if (~aOverriddenProperties & CSSAnimationProperties::Duration) {
      updatedTiming.SetDuration(aNewTiming.Duration());
    }
    if (~aOverriddenProperties & CSSAnimationProperties::IterationCount) {
      updatedTiming.SetIterations(aNewTiming.Iterations());
    }
    if (~aOverriddenProperties & CSSAnimationProperties::Direction) {
      updatedTiming.SetDirection(aNewTiming.Direction());
    }
    if (~aOverriddenProperties & CSSAnimationProperties::Delay) {
      updatedTiming.SetDelay(aNewTiming.Delay());
    }
    if (~aOverriddenProperties & CSSAnimationProperties::FillMode) {
      updatedTiming.SetFill(aNewTiming.Fill());
    }

    animationChanged = oldEffect->SpecifiedTiming() != updatedTiming;
    oldEffect->SetSpecifiedTiming(std::move(updatedTiming));

    if (KeyframeEffect* oldKeyframeEffect = oldEffect->AsKeyframeEffect()) {
      if (~aOverriddenProperties & CSSAnimationProperties::Keyframes) {
        // FIXME(emilio): Should we update the effect target on top if different
        // or something?
        auto* style = oldKeyframeEffect->GetAnimationTarget() == aTarget
                          ? aBuilder.Style()
                          : nullptr;
        oldKeyframeEffect->SetKeyframes(std::move(aNewKeyframes), style,
                                        aTimeline, &aTimelineRange);

        // The default timing function and default composite for CSS Keyframes
        // processing.
        if (auto* cssEffect =
                oldKeyframeEffect->AsCSSAnimationKeyframeEffect()) {
          cssEffect->SetDefaultTimingFunction(aNewTimingFunction);
          cssEffect->SetDefaultComposite(aNewComposite);
        }
      }

      if (~aOverriddenProperties & CSSAnimationProperties::Composition) {
        animationChanged = oldKeyframeEffect->Composite() != aNewComposite;
        oldKeyframeEffect->SetCompositeFromStyle(aNewComposite);
      }
    }
  }

  // Checking pointers should be enough. If both are scroll-timeline, we reuse
  // the scroll-timeline object if their scrollers and axes are the same.
  if (aOld.GetTimeline() != aTimeline) {
    // See `UpdateNamedTimelineAnimation` as to why `SetTimeline` isn't used.
    const bool timelineDidChange = aOld.SetTimelineNoUpdate(
        aTimeline, aTimelineName, Animation::FromJS::No);
    animationChanged = animationChanged || timelineDidChange;
  }

  if (aOld.GetTimelineRange() != aTimelineRange) {
    aOld.SetTimelineRange(std::move(aTimelineRange), Animation::FromJS::No);
    animationChanged = true;
  }

  // Handle changes in play state. If the animation is idle, however,
  // changes to animation-play-state should *not* restart it.
  if (aOld.PlayState() != AnimationPlayState::Idle &&
      ~aOverriddenProperties & CSSAnimationProperties::PlayState) {
    bool wasPaused = aOld.PlayState() == AnimationPlayState::Paused;
    if (!wasPaused && aNewIsStylePaused) {
      aOld.PauseFromStyle();
      animationChanged = true;
    } else if (wasPaused && !aNewIsStylePaused) {
      aOld.PlayFromStyle();
      animationChanged = true;
    }
  }

  // Updating the effect timing above might already have caused the
  // animation to become irrelevant so only add a changed record if
  // the animation is still relevant.
  if (animationChanged && aOld.IsRelevant()) {
    MutationObservers::NotifyAnimationChanged(&aOld);
  }

  if (timelineReferenceChanged && aTimelineName.mName) {
    auto& entries = aTimelineNamesToAnimationMap.LookupOrInsert(
        aTimelineName.mName, nsTArray<RefPtr<CSSAnimation>>{});
    entries.AppendElement(&aOld);
  }
}

void nsAnimationManager::UpdateAnimations(
    dom::Element* aElement, const PseudoStyleRequest& aPseudoRequest,
    const ComputedStyle* aComputedStyle) {
  MOZ_ASSERT(mPresContext->IsDynamic(),
             "Should not update animations for print or print preview");
  MOZ_ASSERT(aElement->IsInComposedDoc(),
             "Should not update animations that are not attached to the "
             "document tree");

  if (!aComputedStyle ||
      (!StaticPrefs::layout_css_display_animations_enabled() &&
       aComputedStyle->StyleDisplay()->mDisplay == StyleDisplay::None)) {
    // If we are in a display:none subtree we will have no computed values.
    // However, if we are on the root of display:none subtree, the computed
    // values might not have been cleared yet.
    // Stop (actually, destroy) any animations here: either there are no
    // computed values, or display animations are disabled and this is a
    // display:none root.
    StopAnimationsForElement(aElement, aPseudoRequest);
    return;
  }

  NonOwningAnimationTarget target(aElement, aPseudoRequest);
  ServoCSSAnimationBuilder builder(aComputedStyle);

  DoUpdateAnimations(target, *aComputedStyle->StyleUIReset(), builder);
}

pub extern "C" fn Servo_StyleSet_GetBaseComputedValuesForElement(
    raw_style_set: &PerDocumentStyleData,
    element: &RawGeckoElement,
    computed_values: &ComputedValues,
    snapshots: *const ServoElementSnapshotTable,
) -> Strong<ComputedValues> {
    debug_assert!(!snapshots.is_null());
    let computed_values = unsafe { ArcBorrow::from_ref(computed_values) };

    let rules = match computed_values.rules {
        None => return computed_values.clone_arc().into(),
        Some(ref rules) => rules,
    };

    let doc_data = raw_style_set.borrow();
    let without_animations_rules = doc_data.stylist.rule_tree().remove_animation_rules(rules);
    if without_animations_rules == *rules {
        return computed_values.clone_arc().into();
    }

    let element = GeckoElement(element);

    let global_style_data = &*GLOBAL_STYLE_DATA;
    let guard = global_style_data.shared_lock.read();
    let shared = create_shared_context(
        &global_style_data,
        &guard,
        &doc_data.stylist,
        TraversalFlags::empty(),
        unsafe { &*snapshots },
    );
    let mut tlc = ThreadLocalStyleContext::new();
    tlc.current_dom_depth = element.as_node().depth();
    let context = StyleContext {
        shared: &shared,
        thread_local: &mut tlc,
    };

    resolve_rules_for_element_with_context(
        element,
        context,
        without_animations_rules,
        &computed_values,
    )
    .into()
}
